c.starter_code:
#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int a[100] = {0};
    int drop[100] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &drop[i]);
    }
    int kept = 0;
    for (int i = 0; i < n; i++) {
        if (drop[i] == 1) {
            printf("%d ", (a[i]));
            kept++;
        }
    }
    if (kept == 0) {
        printf("EMPTY");
    }
    printf("\n");
    return 0;
}

