#include <string.h>

int main(void) {
    int n;
    int l;
    int r;
    scanf("%d", &n);
    scanf("%d", &l);
    scanf("%d", &r);
    int a[100] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    int left = l;
    int right = r;
    while (left < right) {
        int temp = a[left];
        a[left] = a[right];
        a[right] = a[left];
        left++;
        right--;
    }
    for (int i = 0; i < n; i++) {
        printf("%d ", (a[i]));
    }
    printf("\n");
    return 0;
}

