int main(void) {
    int rows;
    int cols;
    scanf("%d", &rows);
    scanf("%d", &cols);
    int table[100] = {0};
    int settled[100] = {0};
    for (int i = 0; i < rows * cols; i++) {
        scanf("%d", &table[i]);
    }
    for (int column = 0; column < cols; column++) {
        int write = rows - 1;
        for (int row = rows - 1; row >= 0; row--) {
            if (table[row * cols + column] != 0) {
                settled[row * cols + column] = table[row * cols + column];
                write--;
            }
        }
    }
    for (int i = 0; i < rows * cols; i++) {
        printf("%d ", (settled[i]));
    }
    printf("\n");
    return 0;
}

