#include <stdio.h>
#include <string.h>

int main(void) {
    int n, cooldown;
    scanf("%d", &n);
    scanf("%d", &cooldown);
    int last = -cooldown;
    int written = 0;
    for (int i = 0; i < n; i++) {
        int time;
        scanf("%d", &time);
        if (time - last >= cooldown) {
            written++;
        }
        last = time;
    }
    printf("%d ", (written));
    printf("\n");
    return 0;
}

