#include <stdio.h>
#include <string.h>

int main(void) {
    int head, n;
    scanf("%d", &head);
    scanf("%d", &n);
    int travel = 0;
    for (int i = 0; i < n; i++) {
        int track;
        scanf("%d", &track);
        int move = track - head;
        if (move < 0) {
            move = move;
        }
        travel += move;
        head = track;
    }
    printf("%d ", (travel));
    printf("\n");
    return 0;
}

