c.starter_code:
#include <stdio.h>
#include <string.h>

int main(void) {
    int capacity, header, n;
    scanf("%d", &capacity);
    scanf("%d", &header);
    scanf("%d", &n);
    int used = 0;
    int accepted = 0;
    for (int i = 0; i < n; i++) {
        int size;
        scanf("%d", &size);
        int extra = size;
        if (size > 0) {
            extra += header;
        }
        if (used + extra <= capacity) {
            used += extra;
            accepted++;
        }
    }
    printf("%d ", (accepted));
    printf("%d ", (used));
    printf("\n");
    return 0;
}

