#include <string.h>

int main(void) {
    int length, n;
    scanf("%d", &length);
    scanf("%d", &n);
    int cursor = 0;
    for (int i = 0; i < n; i++) {
        int origin, offset;
        scanf("%d", &origin);
        scanf("%d", &offset);
        int base = 0;
        if (origin == 1) {
            base = cursor;
        } else if (origin == 2) {
            base = cursor;
        }
        cursor = base + offset;
        if (cursor < 0) {
            cursor = 0;
        }
        if (cursor > length) {
            cursor = length;
        }
    }
    printf("%d ", (cursor));
    printf("\n");
    return 0;
}

