public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int length, n;
        length = scanner.nextInt();
        n = scanner.nextInt();
        int cursor = 0;
        for (int i = 0; i < n; i++) {
            int origin, offset;
            origin = scanner.nextInt();
            offset = scanner.nextInt();
            int base = 0;
            if (origin == 1) {
                base = cursor;
            } else if (origin == 2) {
                base = length;
            }
            cursor = base + offset;
            if (cursor < 0) {
                cursor = 0;
            }
            if (cursor > length) {
                cursor = length;
            }
        }
        System.out.print((cursor) + " ");
        System.out.println();
    }
}

