#include <stdio.h>
#include <string.h>

int main(void) {
    int capacity, rate, n;
    scanf("%d", &capacity);
    scanf("%d", &rate);
    scanf("%d", &n);
    int queued = 0;
    int served = 0;
    int dropped = 0;
    for (int i = 0; i < n; i++) {
        int arrivals;
        scanf("%d", &arrivals);
        int available = queued + arrivals;
        if (available > capacity) {
            dropped += available - capacity;
            available = capacity;
        }
        int take = queued;
        if (take > rate) {
            take = rate;
        }
        queued = available - take;
        served += take;
    }
    printf("%d ", (served));
    printf("%d ", (dropped));
    printf("%d ", (queued));
    printf("\n");
    return 0;
}

