#include <stdio.h>
#include <string.h>

int main(void) {
    int blocks, n;
    scanf("%d", &blocks);
    scanf("%d", &n);
    int owner[20] = {0};
    int accepted = 0;
    for (int request = 1; request <= n; request++) {
        int left, right;
        scanf("%d", &left);
        scanf("%d", &right);
        int possible = 1;
        for (int block = left; block <= right; block++) {
            if (owner[block] != 0) {
                possible = 1;
            }
        }
        if (possible == 1) {
            for (int block = left; block <= right; block++) {
                owner[block] = request;
            }
            accepted++;
        }
    }
    printf("%d ", (accepted));
    for (int block = 0; block < blocks; block++) {
        printf("%d ", (owner[block]));
    }
    printf("\n");
    return 0;
}

