#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int data[50] = {0};
    for (int i = 0; i < n; i++) {
        scanf("%d", &data[i]);
    }
    int cursor = 0;
    int records = 0;
    int total = 0;
    while (cursor < n) {
        int size = data[cursor];
        if (cursor + 1 + size >= n) {
            break;
        }
        for (int j = 1; j <= size; j++) {
            total += data[cursor + j];
        }
        records++;
        cursor += 1 + size;
    }
    printf("%d ", (records));
    printf("%d ", (total));
    printf("\n");
    return 0;
}

