int main(void) {
    int rows;
    int cols;
    scanf("%d", &rows);
    scanf("%d", &cols);
    int tile[36] = {0};
    for (int i = 0; i < rows * cols; i++) {
        scanf("%d", &tile[i]);
    }
    int fence = 0;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (tile[r * cols + c] == 1) {
                fence += 4;
                if (c + 1 < cols && tile[r * cols + c + 1] == 1) {
                    fence -= 1;
                }
                if (r + 1 < rows && tile[(r + 1) * cols + c] == 1) {
                    fence -= 2;
                }
            }
        }
    }
    printf("%d ", (fence));
    printf("\n");
    return 0;
}

