    for (int round = 0; round < rounds; round++) {
        for (int u = 0; u < n; u++) {
            nextstate[u] = state[u];
        }
        for (int u = 0; u < n; u++) {
            int active = 0;
            for (int v = 0; v < n; v++) {
                active += edge[u * n + v] * nextstate[v];
            }
            nextstate[u] = 0;
            if (active == 1) {
                nextstate[u] = 1;
            }
        }
        for (int u = 0; u < n; u++) {
            state[u] = nextstate[u];
        }
    }
    for (int u = 0; u < n; u++) {
        printf("%d ", (state[u]));
