    scanf("%d", &m);
    int rounds;
    scanf("%d", &rounds);
    int edge[144] = {0};
    for (int i = 0; i < m; i++) {
        int u;
        int v;
        scanf("%d", &u);
        scanf("%d", &v);
        edge[u * n + v] = 1;
        edge[v * n + u] = 1;
    }
    int alive[12] = {0};
    int removed[12] = {0};
    for (int u = 0; u < n; u++) {
        alive[u] = 1;
    }
    for (int round = 0; round < rounds; round++) {
        for (int u = 0; u < n; u++) {
            removed[u] = 0;
            if (alive[u] == 1) {
                int degree = 0;
                for (int v = 0; v < n; v++) {
                    degree += edge[u * n + v] * alive[v];
                }
                if (degree <= 1) {
                    alive[u] = 0;
                }
            }
        }
        for (int u = 0; u < n; u++) {
            if (removed[u] == 1) {
                alive[u] = 0;
            }
        }
    }
    int count = 0;
    for (int u = 0; u < n; u++) {
        count += alive[u];
    }
    printf("%d ", (count));
    for (int u = 0; u < n; u++) {
        if (alive[u] == 1) {
            printf("%d ", (u));
        }
    }
    printf("\n");
    return 0;
}

