    int relays;
    int n;
    scanf("%d", &relays);
    scanf("%d", &n);
    int left[8] = {0};
    int fired = 0;
    for (int tick = 0; tick < n; tick++) {
        int op;
        int id;
        int delay;
        scanf("%d", &op);
        scanf("%d", &id);
        scanf("%d", &delay);
        if (op == 1) {
            left[id] = delay;
        } else if (op == 2) {
            left[id] = 0;
        }
        for (int relay = 0; relay < relays; relay++) {
            if (left[relay] > 0) {
                left[relay]--;
                if (left[relay] == 0) {
                    fired++;
                }
            }
        }
    }
    printf("%d ", (fired));
    for (int relay = 0; relay < relays; relay++) {
        printf("%d ", (left[relay]));
    }
    printf("\n");
    return 0;
}

