#include <string.h>

int main(void) {
    int top;
    int n;
    scanf("%d", &top);
    scanf("%d", &n);
    int floor = 0;
    int door = 0;
    int direction = 0;
    int blocked = 0;
    for (int i = 0; i < n; i++) {
        int op;
        scanf("%d", &op);
        if (op == 1 || op == 2) {
            int step = 1;
            if (op == 2) {
                step = -1;
            }
            int next = floor + step;
            if (door == 0 && next >= 0 && next <= top && (direction == 0 || direction == step)) {
                floor = next;
                direction = 0;
            } else {
                blocked++;
            }
        } else if (op == 3) {
            direction = 0;
        } else if (op == 4) {
            if (direction == 0) {
                door = 1;
            } else {
                blocked++;
            }
        } else {
            door = 0;
        }
    }
    printf("%d ", (floor));
    printf("%d ", (door));
    printf("%d ", (direction));
    printf("%d ", (blocked));
    printf("\n");
    return 0;
}

